-- Change journal for incremental backups (generated by scripts/dev/journal-triggers.mjs).
-- Every write to user data is appended to change_log; see scripts/lib/journal.js.
CREATE TRIGGER `journal_foods_i` AFTER INSERT ON `foods` WHEN new.source <> 'swissfcd' BEGIN
	INSERT INTO change_log (at, tbl, op, row_key, data) VALUES (CAST((unixepoch('subsec') * 1000) AS INTEGER), 'foods', 'i', new.id, json_object('id', new.id, 'ref', new.source || ':' || new.source_id, 'source', new.source, 'source_id', new.source_id, 'name_de', new.name_de, 'name_en', new.name_en, 'synonyms', new.synonyms, 'brand', new.brand, 'barcode', new.barcode, 'category', new.category, 'basis', new.basis, 'density', new.density, 'nutrients', json(new.nutrients), 'partial', json(new.partial), 'serving_size', new.serving_size, 'serving_quantity', new.serving_quantity, 'deleted_at', new.deleted_at));
END;
--> statement-breakpoint
